import{uid,day,parseBulk,freshCard,grade,normalizeBackup,shuffle}from'./core.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='lbq.v1';let state={version:1,decks:[],history:[],theme:'light'},storageError=false,storageConflict=false;
try{const raw=localStorage.getItem(KEY);if(raw){const d=JSON.parse(raw);if(d.version!==1||!Array.isArray(d.decks)||!Array.isArray(d.history))throw Error();state=d;}}catch{storageError=true;}
let view='all',activeDeck=null,query='',filter='all',session=null,toastTimer;
const modal=$('#modal');function toast(m){$('#toast').textContent=m;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function save(){if(storageError){toast(storageConflict?'Tab khác đã thay đổi dữ liệu. Hãy tải lại trang trước khi sửa tiếp.':'Dữ liệu cũ chưa đọc được. Hãy xuất dữ liệu gốc trong Cài đặt trước.');return false;}try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('Không thể lưu. Hãy xuất sao lưu ngay để tránh mất dữ liệu.');return false;}}
const all=()=>state.decks.flatMap(d=>d.cards.map(c=>({...c,deckId:d.id,deckName:d.name})));const due=c=>c.due<=Date.now();const deck=id=>state.decks.find(d=>d.id===id);const card=(did,cid)=>deck(did)?.cards.find(c=>c.id===cid);const mastered=d=>d.cards.filter(c=>c.streak>=3).length;const pct=d=>d.cards.length?Math.round(mastered(d)/d.cards.length*100):0;
function open(title,html){$('#modalContent').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon subtle" data-action="close" aria-label="Đóng">×</button></div>${html}`;if(!modal.open)modal.showModal();}
function confirmBox(title,text,fn){open(title,`<p>${esc(text)}</p><div class="form-footer"><button data-action="close">Hủy</button><button class="primary" id="confirm">Xác nhận</button></div>`);$('#confirm').onclick=()=>{modal.close();fn();};}
function download(data,name){const u=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function setTheme(){document.body.classList.toggle('dark',state.theme==='dark');}setTheme();$('#today').textContent=new Date().toLocaleDateString('vi-VN',{weekday:'short',day:'numeric',month:'long'});
function render(){setTheme();$('#dueBadge').textContent=all().filter(due).length;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').textContent=({all:'Bộ câu hỏi',due:'Đến hạn ôn',star:'Đã đánh dấu',stats:'Tiến độ',deck:deck(activeDeck)?.name,study:'Ôn tập'})[view]||'Ôn tập';if(view==='study')return renderStudy();if(view==='deck')return renderDeck();if(view==='stats')return renderStats();renderHome();}
function deckHtml(d){return `<article class="deck ${esc(d.color)}"><div class="row between"><span class="deck-icon">${{purple:'▤',green:'∑',orange:'Aa',blue:'⌘'}[d.color]||'▤'}</span><div class="row"><span class="tag">${esc(d.tag||'Cá nhân')}</span><button class="icon subtle" data-action="deckMenu" data-id="${d.id}" title="Tùy chọn bộ câu hỏi" aria-label="Tùy chọn ${esc(d.name)}">⋯</button></div></div><h3><button class="deck-title" data-action="openDeck" data-id="${d.id}">${esc(d.name)}</button></h3><p class="deck-meta">${d.cards.length} câu hỏi <span>·</span> ${d.cards.filter(due).length} đến hạn</p><div class="progress"><span style="width:${pct(d)}%"></span></div><div class="row between deck-footer"><span>${pct(d)}% đã nắm vững</span><button data-action="studyDeck" data-id="${d.id}">Ôn tập ↗</button></div></article>`;}
function renderHome(){const cards=all(),n=cards.filter(due).length,today=state.history.filter(h=>h.day===day()).length;const title=view==='due'?'Đến lúc ôn lại.':view==='star'?'Những câu cần nhớ.':'Học sâu hơn, từng câu hỏi.';$('#main').innerHTML=`<div class="intro row between wrap"><div><div class="eyebrow">HỌC TẬP CHỦ ĐỘNG</div><h1>${title}</h1><p class="muted">Một không gian nhỏ cho những điều bạn muốn hiểu.</p></div><div class="row"><button data-action="importHome">↥ Nhập nhanh</button><button class="primary" data-action="newDeck">＋ Tạo bộ mới</button></div></div><section class="hero"><div><div class="eyebrow">MỖI NGÀY MỘT CHÚT</div><h2>${n?'Kiến thức đang chờ bạn ôn lại.':'Sẵn sàng cho một điều mới?'}</h2><p>${n?`Bạn có ${n} câu hỏi đến hạn. Bắt đầu từ một câu nhé.`:'Tạo bộ câu hỏi đầu tiên, hoặc khám phá bộ mẫu.'}</p><button class="primary" data-action="${n?'studyDue':'sample'}">${n?'Bắt đầu ôn tập →':'Khám phá bộ mẫu →'}</button></div><div class="hero-art" aria-hidden="true"><div class="paper back"></div><div class="paper front">?</div><span class="spark">✧</span></div></section><div class="summary"><div class="stat"><span class="stat-symbol">▦</span><div><strong>${state.decks.length.toString().padStart(2,'0')}</strong><small>Bộ câu hỏi</small></div></div><div class="stat"><span class="stat-symbol">◷</span><div><strong>${n.toString().padStart(2,'0')}</strong><small>Câu hỏi đến hạn</small></div></div><div class="stat"><span class="stat-symbol">✓</span><div><strong>${today.toString().padStart(2,'0')}</strong><small>Lượt ôn hôm nay</small></div></div></div><div class="row between section-title"><h2>${view==='all'?'Bộ câu hỏi của bạn':view==='due'?'Câu hỏi đến hạn':'Câu hỏi đã đánh dấu'}</h2><small>${view==='all'?state.decks.length+' bộ':cards.filter(view==='due'?due:c=>c.star).length+' câu'}</small></div><div class="filters"><div class="tabs">${['all','recent','weak'].map((f,i)=>`<button data-action="filter" data-id="${f}" class="${filter===f?'selected':''}">${['Tất cả','Mới nhất','Cần ôn lại'][i]}</button>`).join('')}</div><div class="row"><input class="search" id="search" type="search" placeholder="Tìm bộ, câu hỏi, chủ đề…" aria-label="Tìm kiếm" value="${esc(query)}"></div></div><div id="results"></div>`;$('#search').oninput=e=>{query=e.target.value;renderResults();};renderResults();}
function renderResults(){const q=query.toLocaleLowerCase('vi');if(view==='all'){let ds=state.decks.filter(d=>[d.name,d.tag,...d.cards.map(c=>c.q)].join(' ').toLocaleLowerCase('vi').includes(q));if(filter==='recent')ds=[...ds].sort((a,b)=>b.created-a.created);if(filter==='weak')ds=ds.filter(d=>d.cards.some(c=>c.lastWrong));$('#results').innerHTML=`<div class="grid">${ds.map(deckHtml).join('')}<button class="add-card" data-action="newDeck"><strong>＋</strong><span>Tạo bộ câu hỏi mới</span><small>Bắt đầu từ điều bạn tò mò</small></button></div>`;}else{let cs=all().filter(view==='due'?due:c=>c.star).filter(c=>(c.q+' '+c.deckName).toLocaleLowerCase('vi').includes(q));if(filter==='weak')cs=cs.filter(c=>c.lastWrong);if(filter==='recent')cs.reverse();$('#results').innerHTML=cs.length?`<div class="row section-title"><button class="primary" id="practiceFiltered">Ôn ${cs.length} câu này →</button></div><div class="question-list">${cs.map((c,i)=>questionHtml(c,c.deckId,i,true)).join('')}</div>`:'<div class="empty">Chưa có câu hỏi phù hợp.</div>';if($('#practiceFiltered'))$('#practiceFiltered').onclick=()=>studyOptions(cs,'Ôn tập chọn lọc');}}
function questionHtml(c,did,i,hide=false){return `<div class="question-row"><span class="question-number">${String(i+1).padStart(2,'0')}</span><div class="content"><strong>${esc(c.q)}</strong>${hide?`<p>${esc(c.deckName)}</p>`:`<p>${esc(c.a)}</p>`}<div><span class="pill">${c.lastWrong?'Cần ôn lại':c.streak>=3?'Đã nắm vững':c.seen?'Đang học':'Chưa học'}</span></div></div><div class="row"><button class="icon subtle" data-action="star" data-id="${did}" data-card="${c.id}" title="Đánh dấu" aria-label="Đánh dấu" aria-pressed="${c.star}">${c.star?'★':'☆'}</button><button class="icon subtle" data-action="editCard" data-id="${did}" data-card="${c.id}" title="Sửa câu hỏi" aria-label="Sửa câu hỏi">✎</button></div></div>`;}
function renderDeck(){const d=deck(activeDeck);if(!d){view='all';return render();}$('#main').innerHTML=`<button class="subtle" data-action="home">← Bộ câu hỏi</button><div class="intro row between wrap" style="margin-top:18px"><div><div class="eyebrow">${esc(d.tag||'BỘ CÂU HỎI')}</div><h1>${esc(d.name)}</h1><small>${d.cards.length} câu · ${mastered(d)} đã nắm vững</small></div><div class="row wrap"><button data-action="deckMenu" data-id="${d.id}" aria-label="Tùy chọn">⋯</button><button data-action="bulk" data-id="${d.id}">↥ Nhập nhanh</button><button data-action="addCard" data-id="${d.id}">＋ Thêm câu</button><button class="primary" data-action="studyDeck" data-id="${d.id}">Ôn tập →</button></div></div><input class="search" id="cardSearch" placeholder="Tìm trong bộ câu hỏi…" aria-label="Tìm câu hỏi" style="margin-bottom:20px"><div class="question-list" id="cardList"></div>`;const list=q=>{$('#cardList').innerHTML=d.cards.filter(c=>(c.q+' '+c.a).toLocaleLowerCase('vi').includes(q)).map((c,i)=>questionHtml(c,d.id,i)).join('')||'<div class="empty">Chưa có câu hỏi. Thêm câu đầu tiên hoặc nhập hàng loạt.</div>';};list('');$('#cardSearch').oninput=e=>list(e.target.value.toLocaleLowerCase('vi'));}
function editDeck(id,after){const d=deck(id);open(d?'Sửa bộ câu hỏi':'Tạo bộ câu hỏi',`<form id="deckForm"><label for="name">Tên bộ câu hỏi</label><input id="name" required maxlength="160" autofocus placeholder="Ví dụ: Đại số tuyến tính" value="${esc(d?.name||'')}"><label for="tag">Chủ đề</label><input id="tag" maxlength="80" placeholder="Toán học, Tiếng Anh…" value="${esc(d?.tag||'')}"><label for="color">Màu nhận diện</label><select id="color">${['purple','green','orange','blue'].map((c,i)=>`<option value="${c}" ${d?.color===c?'selected':''}>${['Tím','Xanh lá','Cam','Xanh dương'][i]}</option>`).join('')}</select><div class="form-footer"><button type="button" data-action="close">Hủy</button><button class="primary">${d?'Lưu thay đổi':'Tạo bộ câu hỏi'}</button></div></form>`);$('#deckForm').onsubmit=e=>{e.preventDefault();const name=$('#name').value.trim();if(!name)return;const values={name,tag:$('#tag').value.trim(),color:$('#color').value};if(d)Object.assign(d,values);else{const item={id:uid(),...values,created:Date.now(),cards:[]};state.decks.unshift(item);activeDeck=item.id;}save();modal.close();view='deck';render();if(after)bulk(activeDeck);};}
function editCard(did,cid){const d=deck(did),c=card(did,cid);open(c?'Sửa câu hỏi':'Thêm câu hỏi',`<form id="cardForm"><label for="q">Câu hỏi</label><textarea id="q" required maxlength="20000" autofocus placeholder="Bạn muốn gợi mở điều gì?">${esc(c?.q||'')}</textarea><label for="a">Đáp án</label><textarea id="a" required maxlength="30000" placeholder="Ý chính hoặc lời giải đầy đủ">${esc(c?.a||'')}</textarea><label for="hint">Gợi ý (không bắt buộc)</label><textarea id="hint" maxlength="10000" style="min-height:60px">${esc(c?.hint||'')}</textarea><div class="form-footer">${c?'<button type="button" class="danger" id="deleteCard">Xóa câu</button>':'<button type="button" id="saveNext">Lưu & thêm tiếp</button>'}<button class="primary">Lưu câu hỏi</button></div><small>Ctrl/⌘ + Enter: lưu ${c?'':'& thêm tiếp'}</small></form>`);function submit(next){if(!$('#cardForm').reportValidity())return;const values={q:$('#q').value.trim(),a:$('#a').value.trim(),hint:$('#hint').value.trim()};if(!values.q||!values.a)return toast('Câu hỏi và đáp án không được để trống.');if(c)Object.assign(c,values);else d.cards.push(freshCard(values));save();render();if(next){editCard(did);toast('Đã lưu. Tiếp tục câu mới.');}else modal.close();}$('#cardForm').onsubmit=e=>{e.preventDefault();submit(false);};$('#cardForm').onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();submit(!c);}};if(c)$('#deleteCard').onclick=()=>confirmBox('Xóa câu hỏi?','Câu hỏi và tiến độ của câu này sẽ bị xóa.',()=>{d.cards=d.cards.filter(x=>x.id!==cid);save();render();});else $('#saveNext').onclick=()=>submit(true);}
function bulk(did){open('Nhập nhanh',`<p class="muted">Dán hai cột từ Excel, hoặc mỗi dòng: <b>Câu hỏi || Đáp án || Gợi ý</b></p><textarea id="bulkText" rows="9" autofocus placeholder="Đạo hàm của x²? || 2x || Dùng quy tắc lũy thừa\nActive recall là gì? || Chủ động nhớ lại kiến thức"></textarea><label class="check"><input type="checkbox" id="dedup" checked>Bỏ qua câu hỏi trùng nội dung</label><div id="bulkStatus" class="notice">Chưa có nội dung</div><div id="bulkPreview" class="import-preview"></div><div class="form-footer"><button data-action="close">Hủy</button><button class="primary" id="bulkSave" disabled>Thêm câu hỏi</button></div>`);const preview=()=>{const p=parseBulk($('#bulkText').value);$('#bulkStatus').textContent=p.errors.length?`Dòng lỗi: ${p.errors.join(', ')}. Mỗi dòng cần câu hỏi và đáp án, tối đa 1 gợi ý.`:`${p.rows.length} câu hợp lệ`;$('#bulkSave').disabled=!p.rows.length||!!p.errors.length;$('#bulkPreview').innerHTML=p.rows.slice(0,30).map(r=>`<p><b>${esc(r.q)}</b><br>${esc(r.a)}</p>`).join('');};$('#bulkText').oninput=preview;$('#bulkSave').onclick=()=>{const p=parseBulk($('#bulkText').value);if(p.errors.length)return;const d=deck(did),seen=new Set(d.cards.map(c=>c.q.toLocaleLowerCase('vi').trim()));let added=0;for(const r of p.rows){const key=r.q.toLocaleLowerCase('vi');if($('#dedup').checked&&seen.has(key))continue;d.cards.push(freshCard(r));seen.add(key);added++;}save();modal.close();render();toast(`Đã thêm ${added} câu hỏi.`);};}
function deckMenu(id){const d=deck(id);open(d.name,`<div class="question-list"><button data-action="editDeck" data-id="${id}">✎ Đổi tên & chủ đề</button><button data-action="duplicate" data-id="${id}">▣ Nhân bản bộ câu hỏi</button><button data-action="exportDeck" data-id="${id}">↓ Xuất bộ câu hỏi</button><button data-action="resetDeck" data-id="${id}">↺ Đặt lại tiến độ</button><button class="danger" data-action="deleteDeck" data-id="${id}">Xóa bộ câu hỏi</button></div>`);}
function studyOptions(cards,title){if(!cards.length)return toast('Chưa có câu hỏi để ôn.');open('Bắt đầu ôn tập',`<p><b>${esc(title)}</b> <span class="muted">· ${cards.length} câu hỏi</span></p><label for="studyFilter">Phạm vi</label><select id="studyFilter"><option value="all">Tất cả câu hỏi</option><option value="due">Đến hạn ôn</option><option value="wrong">Trả lời sai gần nhất</option><option value="star">Đã đánh dấu</option></select><label for="limit">Số câu trong phiên</label><select id="limit"><option value="0">Tất cả</option><option>10</option><option>20</option><option>50</option></select><label class="check"><input type="checkbox" id="random" checked>Trộn câu hỏi</label><div class="form-footer"><button data-action="close">Hủy</button><button class="primary" id="startStudy">Bắt đầu →</button></div>`);$('#startStudy').onclick=()=>{const f=$('#studyFilter').value;let cs=cards.filter(c=>f==='due'?due(c):f==='wrong'?c.lastWrong:f==='star'?c.star:true);if($('#random').checked)cs=shuffle(cs);const n=Number($('#limit').value);if(n)cs=cs.slice(0,n);if(!cs.length)return toast('Không có câu phù hợp với lựa chọn.');start(cs,title);modal.close();};}
function start(cs,title){session={title,queue:cs.map(c=>({did:c.deckId,cid:c.id})),index:0,correct:0,wrong:[],answer:'',revealed:false,hinted:false,started:Date.now(),done:false};view='study';render();}
function renderStudy(){if(!session){view='all';return render();}const s=session;if(s.index>=s.queue.length){s.done=true;$('#main').innerHTML=`<div class="study result center"><div class="result-circle">${Math.round(s.correct/s.queue.length*100)}%</div><div class="eyebrow">HOÀN THÀNH PHIÊN ÔN</div><h1>Mỗi lần nhớ lại, một lần hiểu sâu.</h1><p class="muted">${s.correct}/${s.queue.length} câu đúng · ${Math.max(1,Math.round((Date.now()-s.started)/60000))} phút</p><div class="row wrap"><button data-action="home">Về bộ câu hỏi</button>${s.wrong.length?'<button class="primary" data-action="retry">Ôn lại câu sai →</button>':'<button class="primary" data-action="studyDue">Tiếp tục ôn →</button>'}</div></div>`;return;}const r=s.queue[s.index],c=card(r.did,r.cid);if(!c){s.index++;return renderStudy();}$('#main').innerHTML=`<div class="study"><div class="row between study-top"><button class="subtle" data-action="exitStudy">← Kết thúc</button><span class="muted">${esc(s.title)}</span><span>${s.index+1} / ${s.queue.length}</span></div><div class="progress"><span style="width:${s.index/s.queue.length*100}%"></span></div><section class="study-card"><div class="row between"><span class="eyebrow">CÂU HỎI ${String(s.index+1).padStart(2,'0')}</span><button class="icon subtle" data-action="star" data-id="${r.did}" data-card="${r.cid}" title="Đánh dấu" aria-label="Đánh dấu" aria-pressed="${c.star}">${c.star?'★':'☆'}</button></div><h2>${esc(c.q)}</h2>${c.hint?`<button class="subtle" data-action="hint">✧ ${s.hinted?'Ẩn gợi ý':'Gợi ý'}</button>${s.hinted?`<div class="hint">${esc(c.hint)}</div>`:''}`:''}<label for="studyAnswer">Câu trả lời của bạn</label><textarea id="studyAnswer" placeholder="Thử nhớ lại bằng lời của bạn…" ${s.revealed?'readonly':''}>${esc(s.answer)}</textarea>${s.revealed?`<div class="answer"><div class="eyebrow">ĐÁP ÁN THAM KHẢO</div>${esc(c.a)}</div><div class="row between wrap"><small>Tự đối chiếu và đánh giá</small><div class="row"><button class="bad" data-action="gradeBad">✕ Chưa đúng <kbd>1</kbd></button><button class="good" data-action="gradeGood">✓ Đúng <kbd>2</kbd></button></div></div>`:`<div class="row between wrap study-bottom"><small>Nhập câu trả lời hoặc xem đáp án ngay.</small><button class="primary" data-action="reveal">Xem đáp án <kbd>Ctrl ↵</kbd></button></div>`}</section><p class="center muted" style="margin-top:22px;font-size:11px">Gợi nhớ → Đối chiếu → Tự đánh giá → Ôn lại</p></div>`;$('#studyAnswer').oninput=e=>{s.answer=e.target.value;};}
function evaluate(correct){const s=session;if(!s||!s.revealed||s.done)return;const r=s.queue[s.index],d=deck(r.did),i=d.cards.findIndex(c=>c.id===r.cid);d.cards[i]=grade(d.cards[i],correct);state.history.push({day:day(),correct,deckId:d.id,at:Date.now()});state.history=state.history.slice(-30000);if(correct)s.correct++;else s.wrong.push(r);save();s.index++;s.answer='';s.revealed=false;s.hinted=false;render();}
function renderStats(){const h=state.history,cs=all(),correct=h.filter(x=>x.correct).length;$('#main').innerHTML=`<div class="intro"><div class="eyebrow">NHÌN LẠI HÀNH TRÌNH</div><h1>Tiến bộ từng chút một.</h1></div><div class="summary"><div class="stat"><div><strong>${h.length}</strong><small>Tổng lượt tự đánh giá</small></div></div><div class="stat"><div><strong>${h.length?Math.round(correct/h.length*100):0}%</strong><small>Tự đánh giá đúng</small></div></div><div class="stat"><div><strong>${cs.filter(c=>c.streak>=3).length}</strong><small>Câu đã nắm vững</small></div></div></div><h2 style="margin-bottom:20px">7 ngày gần đây</h2><div class="deck">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=d.toLocaleDateString('en-CA'),hs=h.filter(x=>x.day===key);return `<div class="history-row"><span>${d.toLocaleDateString('vi-VN',{weekday:'short',day:'numeric',month:'numeric'})}</span><span>${hs.length} lượt · ${hs.filter(x=>x.correct).length} đúng</span></div>`;}).join('')}</div><p class="muted" style="font-size:12px;margin-top:16px">Nắm vững: đúng ít nhất 3 lần liên tiếp. Lịch ôn: 1 → 3 → 7 → 14 → 30 → 60 ngày; câu sai: 10 phút.</p>`;}
function settings(){open('Cài đặt & dữ liệu',`<p class="notice">Dữ liệu lưu trong trình duyệt hiện tại, chưa đồng bộ giữa thiết bị. Xuất sao lưu trước khi xóa dữ liệu trình duyệt hoặc đổi địa chỉ web.</p><div class="question-list"><button data-action="exportAll">↓ Xuất sao lưu toàn bộ</button><button data-action="importFile">↥ Nhập bộ câu hỏi từ JSON</button><button data-action="sample">＋ Thêm bộ mẫu</button><button data-action="toggleTheme">◐ Chuyển sáng / tối</button>${storageError?'<button data-action="rawBackup">Xuất dữ liệu gốc chưa đọc được</button>':''}</div><p class="muted" style="font-size:11px;margin-top:18px">Nhập JSON sẽ thêm bản sao các bộ, giữ tiến độ từng câu; không nhập lịch sử tổng hợp. Không ghi đè dữ liệu đang có.</p>`);}
function sample(){if(state.decks.some(d=>d.name==='Học cách học'))return toast('Bộ mẫu đã có trong danh sách.');const d={id:uid(),name:'Học cách học',tag:'Phương pháp học',color:'purple',created:Date.now(),cards:[['Vì sao tự nhớ lại giúp bạn phát hiện phần chưa hiểu?','Khi không nhìn tài liệu, bạn phải tự tái hiện kiến thức. Phần không diễn đạt được cho thấy chỗ cần học lại.','Thử so sánh đọc lại với tự giải thích.'],['Bạn sẽ biến một định nghĩa thành câu hỏi gợi mở như thế nào?','Hỏi khái niệm đó là gì, vì sao cần nó, lấy ví dụ và nêu một trường hợp không thỏa định nghĩa.','Đi từ ý nghĩa đến ví dụ và phản ví dụ.'],['Sau khi trả lời sai, bước tiếp theo nên là gì?','Đối chiếu đáp án, tìm nguyên nhân sai, diễn đạt lại ý đúng và quay lại ôn sau một khoảng thời gian.','Không chỉ nhìn đáp án rồi chuyển câu.']].map(([q,a,hint])=>freshCard({q,a,hint}))};state.decks.push(d);save();modal.close();render();toast('Đã thêm 3 câu mẫu.');}
const actions={close:()=>modal.close(),home:()=>{view='all';session=null;render();},newDeck:()=>editDeck(),openDeck:id=>{activeDeck=id;view='deck';render();},editDeck:id=>editDeck(id),deckMenu,addCard:id=>editCard(id),editCard:(id,c)=>editCard(id,c),bulk,importHome:()=>{if(!state.decks.length)return editDeck(null,true);open('Nhập vào bộ câu hỏi',`<div class="question-list">${state.decks.map(d=>`<button data-action="bulk" data-id="${d.id}">${esc(d.name)}</button>`).join('')}<button class="primary" id="newForImport">＋ Tạo bộ mới</button></div>`);$('#newForImport').onclick=()=>editDeck(null,true);},filter:id=>{filter=id;renderHome();},star:(id,cid)=>{const c=card(id,cid);c.star=!c.star;save();render();},studyDeck:id=>{const d=deck(id);studyOptions(d.cards.map(c=>({...c,deckId:id})),d.name);},studyDue:()=>studyOptions(all().filter(due),'Câu hỏi đến hạn'),reveal:()=>{session.revealed=true;renderStudy();},hint:()=>{session.hinted=!session.hinted;renderStudy();},gradeGood:()=>evaluate(true),gradeBad:()=>evaluate(false),exitStudy:()=>confirmBox('Kết thúc phiên ôn?','Các câu đã tự đánh giá được giữ lại. Câu chưa đánh giá không thay đổi tiến độ.',()=>{session=null;view='all';render();}),retry:()=>{const cs=session.wrong.map(r=>({...card(r.did,r.cid),deckId:r.did}));start(cs,'Ôn lại câu sai');},duplicate:id=>{const d=deck(id);state.decks.unshift({...d,id:uid(),name:d.name+' (bản sao)',created:Date.now(),cards:d.cards.map(c=>freshCard(c))});save();modal.close();render();toast('Đã nhân bản bộ câu hỏi.');},exportDeck:id=>download({version:1,decks:[deck(id)]},'Learn-by-Question-bo-cau-hoi.json'),exportAll:()=>download(state,'Learn-by-Question-backup.json'),importFile:()=>$('#fileInput').click(),deleteDeck:id=>confirmBox('Xóa bộ câu hỏi?','Toàn bộ câu hỏi trong bộ này sẽ bị xóa. Bạn có thể xuất sao lưu trước.',()=>{state.decks=state.decks.filter(d=>d.id!==id);save();modal.close();render();}),resetDeck:id=>confirmBox('Đặt lại tiến độ?','Lịch ôn và tiến độ từng câu trong bộ sẽ được đặt lại. Lịch sử thống kê vẫn được giữ.',()=>{deck(id).cards=deck(id).cards.map(c=>({...freshCard(c),id:c.id,star:c.star}));save();render();}),sample,toggleTheme:()=>{state.theme=state.theme==='dark'?'light':'dark';save();setTheme();},rawBackup:()=>download(localStorage.getItem(KEY)||'','Learn-by-Question-du-lieu-goc.json')};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)actions[b.dataset.action]?.(b.dataset.id,b.dataset.card);});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{const go=()=>{view=b.dataset.view;query='';session=null;render();};if(session&&!session.done)confirmBox('Rời phiên ôn?','Tiến độ những câu đã đánh giá được giữ lại.',go);else go();});$('#settings').onclick=settings;$('#theme').onclick=actions.toggleTheme;$('#help').onclick=()=>open('Học theo câu hỏi',`<p>1. Tạo bộ → thêm câu hoặc nhập nhanh.</p><p>2. Đọc câu hỏi → thử trả lời → xem đáp án.</p><p>3. Tự đánh giá đúng/sai để lên lịch ôn.</p><p class="notice">App không tự chấm ngữ nghĩa. Bạn đối chiếu với đáp án và tự đánh giá.</p><p><kbd>Ctrl/⌘ + Enter</kbd> Xem đáp án; trong cửa sổ thêm câu: lưu & thêm tiếp.</p><p><kbd>1</kbd> Chưa đúng · <kbd>2</kbd> Đúng (sau khi hiện đáp án, ngoài ô nhập).</p><p><kbd>Esc</kbd> Đóng popup.</p>`);
$('#fileInput').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>20*1024*1024)return toast('Tệp tối đa 20 MB.');try{const ds=normalizeBackup(JSON.parse(await f.text()));confirmBox('Nhập bản sao dữ liệu?',`Thêm ${ds.length} bộ, ${ds.reduce((n,d)=>n+d.cards.length,0)} câu hỏi. Dữ liệu hiện tại được giữ nguyên.`,()=>{state.decks.push(...ds);save();render();toast('Đã nhập các bộ câu hỏi.');});}catch(err){toast(err.message||'Không đọc được tệp JSON.');}};
document.addEventListener('keydown',e=>{if(modal.open||view!=='study'||!session||session.done)return;if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&!session.revealed){e.preventDefault();actions.reveal();}if(!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&session.revealed&&['1','2'].includes(e.key)){e.preventDefault();evaluate(e.key==='2');}});
window.addEventListener('storage',e=>{if(e.key===KEY){toast('Dữ liệu thay đổi ở tab khác. Tải lại trang để dùng bản mới.');storageError=true;storageConflict=true;}});window.addEventListener('beforeunload',e=>{if(session&&!session.done){e.preventDefault();e.returnValue='';}});render();if(storageError)toast('Không đọc được dữ liệu đã lưu. Mở Cài đặt để xuất dữ liệu gốc.');
